        scopeId: scopeKey, scopeKey, kind: 'manifest_missing', descriptor: { displayName: `LIBRA manifest 누락 스코프 · ${scopeKey}` },
        members, links: [], mutations: scopeManagerPurgeMutations(members), coverageComplete: false
